import{_ as e,o as r,c as a,a2 as i}from"./chunks/framework.BbQUUm7J.js";const p=JSON.parse('{"title":"Regulatory Overview","description":"","frontmatter":{},"headers":[],"relativePath":"compliance/regulatory.md","filePath":"compliance/regulatory.md","lastUpdated":1794859264000}'),s={name:"compliance/regulatory.md"};function n(o,t,l,d,c,g){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="regulatory-overview" tabindex="-1">Regulatory Overview <a class="header-anchor" href="#regulatory-overview" aria-label="Permalink to &quot;Regulatory Overview&quot;">​</a></h1><blockquote><p>Condensed from the full <strong>Regulatory, Licensing &amp; Compliance Research Report</strong> embedded in the <a href="https://github.com/FurlPay/furlpay-cli#furlpay-cli--regulatory-licensing-and-compliance-research-report" target="_blank" rel="noreferrer">repository README</a> — the README version is authoritative.</p></blockquote><h2 id="legal-characterization" tabindex="-1">Legal characterization <a class="header-anchor" href="#legal-characterization" aria-label="Permalink to &quot;Legal characterization&quot;">​</a></h2><p>The FurlPay CLI is an enterprise-grade interface integrating payments, cross-chain swaps, tokenized securities/RWAs, decentralized perpetual futures, card issuing and AI agent execution. Client-side non-custodial cryptography (local keystores, hardware signers, local signing) earns the <strong>FinCEN FIN-2019-G001 software safe-harbor only for the pure client↔public-RPC loop</strong>. Several features, once operated as a <em>platform</em>, cross statutory licensing thresholds:</p><ol><li><strong>Hosted API dependencies</strong> — commands coordinating value transfer or relaying sponsored transactions</li><li><strong>x402 clearing facilitator</strong> — a multi-party settlement ledger positions the operator as a settlement institution</li><li><strong>ETSS escrow</strong> — holding/enforcing escrow settlement is statutory escrow activity</li><li><strong>Tokenized securities catalog</strong> — facilitating trades in SEC-regulated funds is broker-dealer/ATS activity</li><li><strong>Perpetual derivatives</strong> — offering leveraged cash-settled contracts to retail violates the CEA without registration</li></ol><h2 id="master-licensing-matrix-summary" tabindex="-1">Master licensing matrix (summary) <a class="header-anchor" href="#master-licensing-matrix-summary" aria-label="Permalink to &quot;Master licensing matrix (summary)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature surface</th><th>United States</th><th>European Union</th><th>United Kingdom</th><th>Singapore</th></tr></thead><tbody><tr><td>A2A transfers &amp; relayed payments</td><td>FinCEN MSB + 49 state MTLs (NMLS)</td><td>MiCA CASP Class 2 / EMI</td><td>FCA MLRs registration + API</td><td>MAS MPI (PSA 2019)</td></tr><tr><td>Cross-chain swaps &amp; CCTP</td><td>MSB (VC exchanger)</td><td>MiCA CASP Class 2</td><td>Registered cryptoasset firm</td><td>DPT service license</td></tr><tr><td>Tokenized stocks (JQQQ, NVDA, FOBXX)</td><td>SEC broker-dealer + FINRA + Form ATS</td><td>MiFID II investment firm / MTF</td><td>Part 4A permission + MTF</td><td>CMS license + RMO</td></tr><tr><td>Perpetuals &amp; margin</td><td>CFTC FCM/DCM — <strong>US retail prohibited</strong>; ECP validation or geoblocking</td><td>MiFID II derivatives venue</td><td><strong>Retail crypto-derivatives ban</strong></td><td>CMS license (capital markets products)</td></tr><tr><td>Card issuing</td><td>BaaS sponsor bank + PCI-DSS L1</td><td>EMI + Visa associate membership</td><td>AEMI</td><td>MPI (account issuance)</td></tr><tr><td>x402 clearing</td><td>MSB / state MTLs</td><td>MiCA CASP</td><td>PSR 2017</td><td>Merchant acquisition (PSA)</td></tr><tr><td>Dispute escrow</td><td>State escrow licenses (e.g., CA DFPI)</td><td>Payment institution / trust</td><td>SPI or trust authorization</td><td>Trust Business Act license</td></tr></tbody></table><h2 id="key-statutes-precedents" tabindex="-1">Key statutes &amp; precedents <a class="header-anchor" href="#key-statutes-precedents" aria-label="Permalink to &quot;Key statutes &amp; precedents&quot;">​</a></h2><ul><li><strong>US money transmission:</strong> BSA 31 U.S.C. § 5330; 31 CFR § 1022.380; FIN-2019-G001; MTMA state harmonization (NMLS, tangible-net-worth floors, surety bonding, permissible-investment rules); NY BitLicense / Limited Purpose Trust</li><li><strong>US securities:</strong> Exchange Act § 15(a) (broker-dealer); FINRA Rule 1014; Regulation ATS (Rules 300–303); Rule 15c3-3 customer protection; Rule 506(c) accredited-investor verification</li><li><strong>US derivatives:</strong> CEA § 2(c)(2)(D) and § 4(a); ECP standard (7 U.S.C. § 1a(18), $10M assets); <em>CFTC v. bZeroX/Ooki DAO</em> (2022/23); CFTC orders vs Deridex/Opyn/ZeroEx (2023); Uniswap Labs settlement (2024) — <strong>front-end interfaces carry registration liability</strong></li><li><strong>EU:</strong> MiCA (Regulation (EU) 2023/1114) — CASP Classes 1–3 (€50k/€125k/€150k capital + 25% fixed-overheads prudential floor); EMT framework for fiat stablecoins; MiFID II for tokenized financial instruments (€150k–€730k) + DORA</li><li><strong>UK:</strong> FCA MLRs 2017 cryptoasset registration; FSMA 2023; <strong>PS20/10 retail crypto-derivatives ban</strong></li><li><strong>Singapore:</strong> PSA 2019 (MPI above S$3M monthly / S$5M e-money; S$250k capital, S$100k security deposit, PSN07 asset segregation with ≥50% cold storage); SFA for CMS/RMO</li></ul><h2 id="travel-rule-sanctions" tabindex="-1">Travel rule &amp; sanctions <a class="header-anchor" href="#travel-rule-sanctions" aria-label="Permalink to &quot;Travel rule &amp; sanctions&quot;">​</a></h2><ul><li>FATF Recommendation 16 / FinCEN 31 CFR § 1010.410 / EU ToFR 2023/1113: transfers above <strong>$3,000</strong> (€1,000 EU) must transmit verified originator/beneficiary IVMS101 data to the receiving VASP</li><li>Pre-flight OFAC SDN (plus UK HMT / EU / UN) screening on source and destination addresses; fail-closed abort on sanctioned-mixer or jurisdiction exposure</li></ul><h2 id="capital-timeline-reality" tabindex="-1">Capital &amp; timeline reality <a class="header-anchor" href="#capital-timeline-reality" aria-label="Permalink to &quot;Capital &amp; timeline reality&quot;">​</a></h2><p>Full multi-jurisdiction licensing is a <strong>$3.5M–$10M+ capital, $13M–$28M aggregate surety-bond</strong> undertaking over ~24 months. The report&#39;s phased roadmap:</p><ol><li><strong>Phase 1 (months 1–6):</strong> pure non-custodial client; partner rails (BaaS/Circle/Stripe); FinCEN MSB for treasury; hard US geoblocking of perps</li><li><strong>Phase 2 (6–14):</strong> EU MiCA CASP Class 2 entity; Singapore MPI; global Travel Rule integration</li><li><strong>Phase 3 (14–24+):</strong> 49-state MTL rollout; FINRA broker-dealer (Form BD) + Form ATS; state escrow licenses</li></ol><p>The complete capital tables, surety-bond math, sequence diagrams and vendor stack (Persona/Sumsub, Chainalysis/TRM, Castellum, Notabene/TRISA, Hummingbird) are in the README report.</p>',15)])])}const m=e(s,[["render",n]]);export{p as __pageData,m as default};
